-- /care-audits marketing page: covers the audit features from PRs #202 to #207.
-- Apply only once those PRs are live. Images 7 to 11 are placeholders until the real ones are supplied.
update service_pages set content = $cs${"toc": [], "lede": ["Regular audits are a CQC expectation, but completing them manually is slow, inconsistently formatted, and rarely produces findings that lead to clear action. CareStream gives you over 30 ready-made audits, lets you build or import your own, schedules them to the right people, and turns every finding into an action that is followed through and re-checked at the next audit."], "blocks": [{"id": "", "flip": false, "kind": "cards", "tint": true, "image": null, "intro": ["A care manager filling in a paper audit form or a spreadsheet can spend two to three hours on a single audit. The questions vary from month to month depending on who does it. The resulting report is filed, a few actions are noted, and the cycle repeats with the same weaknesses.", "CQC inspectors want to see that internal audits are consistent, that they produce clear findings, and that those findings come with sensible actions. CareStream gives every audit the same structure, scores each section as you go, and turns your answers into a formatted report with prioritised recommendations."], "label": "The Problem With Manual Audits", "parts": [{"sub": "", "kind": "cards", "items": [{"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["A manager spends two hours on a spreadsheet. The format changes each time. Findings are noted but inconsistently. The audit exists on paper but rarely reads the same way twice."], "title": "Traditional manual audit", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["A structured audit is completed in the hub in well under an hour. Every section is scored, findings and actions are captured against each question, and a formatted report with AI recommendations is generated the moment you finish."], "title": "CareStream audit", "marker": "", "bullets": []}], "where": "", "footer": "", "header": "", "bullets": [], "variant": "inplace c2"}], "split": false, "narrow": false, "actions": [], "heading": "Most care setting audits take too long, read differently every time, and rarely lead to action."}, {"id": "", "flip": false, "kind": "cards", "tint": false, "image": null, "intro": ["Choose from over 30 ready-made audits covering the areas CQC inspects, or use your own. Your team works through each one section by section on the web or in the hub, and the signed report is generated the moment the audit is complete."], "label": "How CareStream Audits Work", "parts": [{"sub": "", "kind": "cards", "items": [{"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["CareStream includes over 30 ready-made audits, from medicines, infection control and fire safety to safeguarding, falls, pressure care, mealtimes, water safety and night shift walkrounds. Start one yourself, or schedule it to a named person with a due date."], "title": "Choose the audit and start", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Work through the audit section by section on a phone, tablet or computer. Questions can be yes or no, a reading with a pass range, a rating or a choice, and follow-up questions only appear when they apply. Answers save as you go, so you can pause and pick up later on any device."], "title": "Guided, structured completion in the hub", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["When the audit is signed and complete, CareStream produces a PDF report with every answer, each section score, your findings, signatures and AI recommendations. It is saved with the audit and emailed to your managers automatically."], "title": "Signed PDF report, generated automatically", "marker": "", "bullets": []}], "where": "", "footer": "", "header": "", "bullets": [], "variant": "inplace c3"}], "split": false, "narrow": false, "actions": [], "heading": "Choose it, work through it, receive your report. No formatting, no spreadsheets."}, {"id": "", "flip": false, "kind": "cards", "tint": true, "image": null, "intro": ["Every service audits things the standard templates do not cover. Build your own audit in minutes, import the one you already use, or copy a ready-made audit and adapt it. Your audits work exactly like the built-in ones."], "label": "Build Your Own Audits", "parts": [{"sub": "", "kind": "cards", "items": [{"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Add sections and choose a type for every question: yes or no, a number with a pass range such as fridge temperatures, a date, a choice, a rating, or written findings. Follow-up questions can appear only when an earlier answer needs them."], "title": "Audit anything, your way", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Tag each question with the CQC quality statement it evidences, so every report shows inspectors exactly which part of the framework your audit covers."], "title": "Tagged to CQC quality statements", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Copy any ready-made audit to make it your own and hide the ones you do not use. Every change is saved as a new version with a note of what changed, and completed audits keep the questions they were answered against."], "title": "Copy, hide and keep versions", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Every audit, custom or built-in, gets scoring, signatures, a PDF report, AI recommendations mapped to the CQC key questions, an action plan and trends over time."], "title": "Inspection-ready, automatically", "marker": "", "bullets": []}], "where": "", "footer": "", "header": "", "bullets": [], "variant": "inplace c4"}], "split": false, "narrow": false, "actions": [], "heading": "Not just our templates, your audits too."}, {"id": "", "flip": false, "kind": "prose", "tint": false, "image": "/images/our-services/care-audits/7.webp", "intro": ["Upload the audit you use today as a PDF, a Word document or simply a photo of the paper form. AI reads it, including scanned and handwritten forms, and turns it into a CareStream audit with the sections, question types, options and CQC tags filled in.", "You check it in the audit builder before anything is saved, with anything the AI was unsure about highlighted for you. Years of audits your team already trusts can be up and running in minutes."], "label": "Import Your Existing Audits", "parts": [], "split": true, "narrow": false, "actions": [], "heading": "Already have audits on paper or in Word? Upload them and CareStream does the typing."}, {"id": "", "flip": true, "kind": "ticks", "tint": true, "image": "/images/our-services/care-audits/2.webp", "intro": ["Build your own audit, link it to the training it measures, and CareStream shows you whether that training is actually improving practice. It joins up the whole cycle, in one place."], "label": "Link Audits to Training", "parts": [{"sub": "", "kind": "ticks", "items": [], "where": "in", "footer": "", "header": "", "bullets": ["It needs a few monthly audit runs to show a meaningful trend, and it shows a correlation rather than proof of cause. Even so, it is exactly the train, audit, improve and re-audit cycle that CQC's well-led question looks for."], "variant": ""}, {"sub": "", "kind": "cards", "items": [{"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Add your own policy documents. They become the single source of truth everything else is built from."], "title": "Upload your policies", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["CareStream creates training modules grounded in your policies, so staff learn your way of working, not a generic course."], "title": "Training generated from them", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Create an audit for the practice that training should improve, and link it to the module. The audit becomes your real-world measure of whether it worked."], "title": "Build an audit, linked to the training", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["CareStream tracks the audit's compliance score against training completion over time, so you can see whether the training is landing in practice."], "title": "See the training impact", "marker": "", "bullets": []}], "where": "after", "footer": "", "header": "", "bullets": [], "variant": "hoisted c4"}], "split": true, "narrow": false, "actions": [], "heading": "Close the loop, from policy to proven impact."}, {"id": "", "flip": false, "kind": "prose", "tint": false, "image": "/images/our-services/care-audits/3.webp", "intro": ["The guided audit walks you through every required question in the right order. Each question takes a Yes, No or Not Applicable, with space for what you found and the action to take, so every audit is formatted the same way regardless of who completes it.", "It can be completed on any device, at any time. Answers save as you go, so a manager finishing a medicines audit at the end of a shift takes the same structured path as one completing it at the start of the day.", "A clear answer and a note for every question, formatted identically every time."], "label": "See It In Action", "parts": [], "split": true, "narrow": false, "actions": [], "heading": "Every question is consistent, and every answer is captured in the same structure."}, {"id": "", "flip": true, "kind": "cards", "tint": true, "image": "/images/our-services/care-audits/8.webp", "intro": ["Schedule each audit to a named member of staff with a due date and a repeat, daily, weekly, monthly or quarterly. It appears in their hub under Assigned to you, and the next one is set up automatically when they finish."], "label": "Scheduling and Reminders", "parts": [{"sub": "", "kind": "cards", "items": [{"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["The assigned person is emailed when an audit is assigned, two days before it is due, and when it becomes overdue."], "title": "Reminders before and after", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Choose how many days overdue an audit can be before it is escalated to your managers, so nothing slips quietly."], "title": "Escalation you control", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Admins get a daily or weekly summary of what is due, overdue, done and missed across the home."], "title": "A summary for managers", "marker": "", "bullets": []}], "where": "in", "footer": "", "header": "", "bullets": [], "variant": "stack3"}], "split": true, "narrow": false, "actions": [], "heading": "The right audit, with the right person, on the right day."}, {"id": "", "flip": false, "kind": "cards", "tint": false, "image": "/images/our-services/care-audits/4.webp", "intro": ["When you spot something as you walk the floor, take a photo there and then. On a phone or tablet, your team can attach photos to any audit question as they go, and draw on them to circle or point at the problem. The photos are compressed automatically and stored against that exact question, so the evidence is right there beside the answer."], "label": "Photo evidence", "parts": [{"sub": "", "kind": "cards", "items": [{"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["When a manager or inspector reviews the completed audit, the photos appear beneath each question. Click any thumbnail to open it full size as part of your evidence trail."], "title": "Every photo is waiting when the audit is reviewed.", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["The evidence sits right under the answer, so anyone opening the audit can see exactly what was checked and what it looked like, not just a Yes or a No."], "title": "Attached to the exact question in the staff hub.", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Out on the floor, tap Add to snap a photo or choose one from the gallery, then circle or arrow the problem before it is saved. Each image attaches to the question you are on, and they are compressed automatically so they upload quickly, even on care home wifi."], "title": "Take or upload photos on a phone or tablet, question by question.", "marker": "", "bullets": []}], "where": "in", "footer": "", "header": "", "bullets": [], "variant": "stack3"}], "split": true, "narrow": false, "actions": [], "heading": "Capture the evidence, right on the question."}, {"id": "", "flip": true, "kind": "prose", "tint": true, "image": "/images/our-services/care-audits/9.webp", "intro": ["The auditor signs on screen with a finger or mouse to confirm the audit is a true record. Turn on manager approval and the completed audit goes to your care manager in the hub, who reviews it and signs it off.", "Both signatures, names and dates are saved with the audit and printed on the PDF report, giving inspectors a clear record of who carried out each audit and who checked it."], "label": "Signatures and Sign-off", "parts": [], "split": true, "narrow": false, "actions": [], "heading": "Signed by the auditor. Approved by the manager. Recorded on the report."}, {"id": "", "flip": false, "kind": "prose", "tint": false, "image": "/images/our-services/care-audits/5.webp", "intro": ["The moment the audit is signed and complete, the PDF report is ready. It includes every answer and finding, each section score, the CQC quality statements covered, signatures and the AI recommendations. It is saved with the audit, emailed to your managers automatically, and can be downloaded again at any time to share or present to a CQC inspector."], "label": "The Finished Report", "parts": [], "split": true, "narrow": false, "actions": [], "heading": "A signed PDF report with every response, every section score, and your summary. Generated instantly."}, {"id": "", "flip": true, "kind": "cards", "tint": true, "image": "/images/our-services/care-audits/6.webp", "intro": ["CareStream reads the responses from each completed audit and generates specific, prioritised recommendations based on what your findings actually show. Not generic advice from a template. Every recommendation is drawn from the answers you gave and the actions you recorded in that audit.", "Each recommendation references the specific finding it is based on, the risk it addresses, a suggested action, and a priority level, so managers can act immediately without having to interpret the audit data themselves.", "Each completed audit is stored alongside its recommendations and an overall AI rating of Outstanding, Good, Requires Improvement, or Inadequate, giving you a clear, consistent picture of where the service stands at the end of every audit.", "Recommendations tied directly to the findings that generated them."], "label": "AI-Generated Recommendations", "parts": [{"sub": "", "kind": "cards", "items": [{"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Recommendations reference the exact questions that returned a No, not the audit as a whole."], "title": "Specific to your findings", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Each recommendation carries a clear priority so the management team knows what to deal with first."], "title": "Prioritised for you", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Every completed audit is given an Outstanding, Good, Requires Improvement, or Inadequate rating based on the responses."], "title": "An overall rating", "marker": "", "bullets": []}], "where": "after", "footer": "", "header": "", "bullets": [], "variant": "hoisted c3"}], "split": true, "narrow": false, "actions": [], "heading": "Every completed audit generates a prioritised improvement plan. Automatically."}, {"id": "", "flip": false, "kind": "cards", "tint": false, "image": "/images/our-services/care-audits/10.webp", "intro": ["Findings only matter if they get fixed. CareStream turns recommendations into an action plan you assign to staff, and follows each action through to proof that it worked."], "label": "Closing Actions", "parts": [{"sub": "", "kind": "cards", "items": [{"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Review the drafted action plan, set priorities and due dates, and assign each action. It appears in that person's hub under My actions, with reminders if it goes overdue."], "title": "Assigned to named staff", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Staff close an action by saying what they did and adding photos of the fix. If they need longer, they ask for more time with a reason and a manager agrees or declines it."], "title": "Evidence of the fix", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["When the same audit is next carried out, the auditor checks each previous action is still fixed. Anything that is not is reopened automatically."], "title": "Re-checked at the next audit", "marker": "", "bullets": []}], "where": "in", "footer": "", "header": "", "bullets": [], "variant": "stack3"}], "split": true, "narrow": false, "actions": [], "heading": "Every action followed through, evidenced and re-checked."}, {"id": "", "flip": true, "kind": "prose", "tint": true, "image": "/images/our-services/care-audits/11.webp", "intro": ["Every completed audit feeds the Trends panel: the percentage of checks met over the last 3 to 24 months, each audit's latest score and how it has changed, and which questions fail most often.", "Repeat failures, the same check failing in audit after audit, are flagged first, because they usually mean an action has not worked. If you run more than one home, compare their audit scores side by side."], "label": "Trends and Repeat Failures", "parts": [], "split": true, "narrow": false, "actions": [], "heading": "See whether quality is improving, and spot the problems that keep coming back."}, {"id": "", "flip": false, "kind": "cards", "tint": false, "image": null, "intro": ["CareStream gives every audit the same structure, scores it as you go, and turns your answers into a formatted, inspection-ready report."], "label": "A Complete Audit Toolkit", "parts": [{"sub": "", "kind": "cards", "items": [{"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Medicines, infection control, health and safety, fire, safeguarding, falls, pressure care, mealtimes, water safety, night shift walkrounds, HR files and more. All ready to use, and you can build or import your own."], "title": "Over 30 ready-made audits", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Every answer is scored as you go, including readings outside their pass range and ratings below the pass mark, so you can see which sections are strong and which need attention before you finish."], "title": "Section-by-section scoring", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Answers save automatically as you work. Pause an audit and pick it up later on any device, exactly where you left off."], "title": "Auto-save and resume", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Run audits room by room, one resident or staff member at a time, or by day or night shift, so the record matches how the audit is actually carried out."], "title": "Room, resident, staff and shift audits", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Each completed audit is signed, saved as a PDF and emailed to your managers, ready to present directly to a CQC inspector."], "title": "Signed PDF reports", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Every completed audit generates prioritised recommendations from your findings, plus an overall rating of Outstanding, Good, Requires Improvement, or Inadequate."], "title": "AI recommendations and rating", "marker": "", "bullets": []}], "where": "", "footer": "", "header": "", "bullets": [], "variant": "inplace c3"}], "split": false, "narrow": false, "actions": [], "heading": "From guided completion to section scoring to AI recommendations. One place for the whole audit."}, {"id": "", "flip": false, "kind": "table", "tint": true, "image": null, "intro": ["CQC inspectors assess whether internal audits are consistent, whether they produce clear findings, and whether those findings are acted on. CareStream records the evidence for all three, and shows the fix was checked."], "label": "CQC Evidence", "parts": [{"sub": "", "head": ["What CareStream records", "What this shows an inspector"], "kind": "table", "rows": [["Signed PDF report for every audit", "A formatted report for every completed audit, with section scores, findings, actions and signatures. The same format regardless of who completed it."], ["Section scores", "A clear score for each section of the audit, showing which areas were met in full and which were flagged for action on the day."], ["Findings and actions on every question", "Each question carries the outcome of the audit and the action to be taken, so inspectors can see findings are noted and followed with a clear next step."], ["CQC quality statement tags", "Each question is linked to the quality statement it evidences, so inspectors can see how your audits map to the Single Assessment Framework."], ["AI recommendations and overall rating", "Each completed audit is stored with prioritised recommendations and an Outstanding, Good, Requires Improvement, or Inadequate rating, showing a structured approach to quality improvement."], ["A timestamped completion record", "Every audit shows who completed it and when, demonstrating that audits are carried out and recorded as part of the routine of the service."], ["Manager sign-off", "The auditor and the approving manager both sign, with names and dates on the report, showing audits are checked as well as completed."], ["Actions closed with evidence and re-checked", "Each action records who fixed it, what they did, photos of the fix, and whether it was still fixed at the next audit. The improve and re-audit cycle the well-led question looks for."], ["Trends and repeat failures", "Scores over time and checks that keep failing, showing you monitor quality and act when something is not improving."], ["Scheduled audits and version history", "Who each audit was assigned to, when it was due and done, and every change made to your audits, showing a planned, controlled audit programme."]], "items": [], "where": "", "footer": "", "header": "", "bullets": [], "variant": "inplace"}], "split": false, "narrow": false, "actions": [], "heading": "An audit record that shows inspectors a consistent, structured approach to quality."}, {"id": "", "flip": false, "kind": "cards", "tint": false, "image": null, "intro": [], "label": "Everything Included", "parts": [{"sub": "", "kind": "cards", "items": [{"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Medicines, infection control, health and safety, fire, safeguarding, falls, pressure care, mealtimes, water safety, HR files and more. Use them as they are, copy them, or build your own."], "title": "Over 30 ready-made audits", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Work through each audit section by section with a clear Yes, No or Not Applicable and notes on every question. Consistent regardless of who completes it."], "title": "Guided, structured completion", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["A PDF report with section scores, findings, signatures and AI recommendations is saved and emailed the moment the audit is complete."], "title": "Signed PDF reports", "marker": "", "bullets": []}, {"tag": "", "flag": "", "icon": [{"d": "M12 4v5M12 15v5M4 12h5M15 12h5", "tag": "path"}, {"r": "2.6", "cx": "12", "cy": "12", "tag": "circle"}], "tone": "", "paras": ["Every answer is scored as you go, so you can see which sections are strong and which need attention before you finish."], "title": "Section-by-section scoring", "marker": "", "bulle